vrml.40:
#X3D V4.1 utf8 X_ITE V16.5.0

PROFILE Interchange

COMPONENT EnvironmentalSensor : 3
COMPONENT PointingDeviceSensor : 1
COMPONENT Scripting : 1
COMPONENT Sound : 3
COMPONENT Text : 2

Viewpoint {
  position 0 0 0
}

Sound {
  location 0 0 -5
  minBack 20
  minFront 20
  maxBack 40
  maxFront 40
  source DEF O AudioClip {
    url [
      "media/bad.mid",
      "media/tone48k-stereo.wav"
    ]
    loop TRUE
    startTime 946684800.048
    stopTime 1
  }
}

DEF PO Script {
  inputOnly SFBool a
  inputOnly SFTime d

  url "javascript:
function a (v, t) { print ('O active ' + v + ' ' + t); }
function d (v, t) { print ('O duration ' + v + ' ' + t); }
"
}

DEF T TimeSensor {
  cycleInterval 0.5
  loop TRUE
}

DEF S Script {
  inputOnly      SFTime  set_time
  outputOnly     SFTime  start
  initializeOnly SFInt32 n 49

  url "javascript:
function set_time (value) { if (++ n === 12) start = value; }
"
}

ROUTE O.isActive TO PO.a
ROUTE O.duration_changed TO PO.d
ROUTE T.time TO S.set_time
ROUTE S.start TO O.set_startTime
